import random
from collections import deque

def bfs_dist(adj, u, v, n):
    """BFS distance from u to v"""
    dist = [-1] * n
    dist[u] = 0
    q = deque([u])
    while q:
        x = q.popleft()
        if x == v:
            return dist[v]
        for nb in adj[x]:
            if dist[nb] == -1:
                dist[nb] = dist[x] + 1
                q.append(nb)
    return float('inf')

def compute_girth(adj, n):
    """Compute girth of graph"""
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        q = deque([(start, -1)])
        while q:
            u, parent = q.popleft()
            for v in adj[u]:
                if v == parent:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append((v, u))
                else:
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle

def check_3colorable(adj, n):
    """Check if graph is 3-colorable using backtracking"""
    color = [-1] * n
    def bt(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if color[u] != -1:
                used.add(color[u])
        for c in range(3):
            if c not in used:
                color[v] = c
                if bt(v+1):
                    return True
                color[v] = -1
        return False
    return bt(0)

def random_3colorable_high_girth(n=19, target_edges=37, max_iter=5000):
    best_edges_list = []
    best_count = 0

    for trial in range(max_iter):
        # Random partition into 3 color classes
        partition = list(range(n))
        random.shuffle(partition)
        # Try different splits
        s = random.choice([(6,6,7), (5,7,7), (6,7,6), (7,6,6)])
        A = set(partition[:s[0]])
        B = set(partition[s[0]:s[0]+s[1]])
        C = set(partition[s[0]+s[1]:])

        # Build possible edges (between different color classes)
        possible_edges = []
        for a in A:
            for b in B:
                possible_edges.append((min(a,b), max(a,b)))
        for b in B:
            for c in C:
                possible_edges.append((min(b,c), max(b,c)))
        for a in A:
            for c in C:
                possible_edges.append((min(a,c), max(a,c)))

        random.shuffle(possible_edges)

        # Greedily add edges while maintaining girth >= 8
        adj = [set() for _ in range(n)]
        edges = []

        for e in possible_edges:
            u, v = e
            # Check distance before adding
            d = bfs_dist(adj, u, v, n)
            if d >= 7:  # adding edge creates cycle of length d+1 >= 8
                adj[u].add(v)
                adj[v].add(u)
                edges.append(e)

        ne = len(edges)
        if ne > best_count:
            best_count = ne
            best_edges_list = edges[:]
            print(f"Trial {trial}: {ne} edges")
            if ne >= target_edges:
                return best_edges_list, ne

    return best_edges_list, best_count

random.seed(42)
result, ne = random_3colorable_high_girth(19, 37, 5000)
print(f"\nBest found: {ne} edges")
if result:
    # Verify
    n = 19
    adj = [set() for _ in range(n)]
    for u, v in result:
        adj[u].add(v)
        adj[v].add(u)
    g = compute_girth(adj, n)
    print(f"Girth: {g}")
    c3 = check_3colorable(adj, n)
    print(f"3-colorable: {c3}")
